import React, { useState, useEffect } from 'react';
import {
  SafeAreaView,
  View,
  Text,
  TouchableOpacity,
  StatusBar,
  StyleSheet, // ✅ FIX LỖI 2304: đã import
} from 'react-native';
import { Activity } from 'lucide-react-native';

import { useUsbSerial } from './src/hooks/useUsbSerial';
import OnboardingScreen from './src/screens/OnboardingScreen';
import MeasureScreen from './src/screens/MeasureScreen';
import AiInsightsScreen from './src/screens/AiInsightsScreen';

type Tab = 'onboarding' | 'measure' | 'ai';

const App: React.FC = () => {
  const {
    usbServiceStarted,
    usbAttached,
    connected,
    isMeasuring,
    lastReading,
    log,
    handleStartMeasure,
    statusText,
  } = useUsbSerial();

  const [activeTab, setActiveTab] = useState<Tab>('onboarding');
  const [relativeEmail, setRelativeEmail] = useState('');

  return (
    <SafeAreaView style={styles.root}>
      <StatusBar barStyle="light-content" />

      {/* HEADER */}
      <View style={styles.header}>
        <View style={styles.headerLeft}>
          <View style={styles.headerIcon}>
            <Activity size={18} color="#ffffff" />
          </View>
          <View>
            <Text style={styles.headerTitle}>PicoBP – USB CDC</Text>
            <Text style={styles.headerSub}>
              ESP32 đo huyết áp • Kết nối USB
            </Text>
          </View>
        </View>

        <View
          style={[
            styles.badge,
            connected ? styles.badgeOnline : styles.badgeOffline,
          ]}
        >
          <Text style={styles.badgeText}>
            {connected ? 'ONLINE' : 'OFFLINE'}
          </Text>
        </View>
      </View>

      {/* BODY */}
      <View style={styles.body}>
        {/* TAB BAR */}
        <View style={styles.tabBar}>
          <TabButton
            label="BẮT ĐẦU"
            active={activeTab === 'onboarding'}
            onPress={() => setActiveTab('onboarding')}
          />
          <TabButton
            label="ĐO USB"
            active={activeTab === 'measure'}
            onPress={() => setActiveTab('measure')}
          />
          <TabButton
            label="AI INSIGHTS"
            active={activeTab === 'ai'}
            onPress={() => setActiveTab('ai')}
          />
        </View>

        {/* SCREENS */}
        {activeTab === 'onboarding' && (
          <OnboardingScreen
            relativeEmail={relativeEmail}
            setRelativeEmail={setRelativeEmail}
          />
        )}

        {activeTab === 'measure' && (
          <MeasureScreen
            usbServiceStarted={usbServiceStarted}
            usbAttached={usbAttached}
            connected={connected}
            isMeasuring={isMeasuring}
            lastReading={lastReading}
            log={log}
            statusText={statusText}
            onStartMeasure={handleStartMeasure}
          />
        )}

        {activeTab === 'ai' && (
          <AiInsightsScreen
            relativeEmail={relativeEmail}
            lastReading={lastReading}
          />
        )}
      </View>
    </SafeAreaView>
  );
};

/* ---------- TAB BUTTON ---------- */
type TabButtonProps = {
  label: string;
  active: boolean;
  onPress: () => void;
};

const TabButton: React.FC<TabButtonProps> = ({ label, active, onPress }) => (
  <TouchableOpacity
    onPress={onPress}
    style={[styles.tabItem, active && styles.tabItemActive]}
  >
    <Text style={[styles.tabText, active && styles.tabTextActive]}>
      {label}
    </Text>
  </TouchableOpacity>
);

/* ---------- STYLES ---------- */
const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: '#0ea5e9', // xanh da trời
  },

  header: {
    paddingHorizontal: 16,
    paddingVertical: 12,
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },

  headerLeft: {
    flexDirection: 'row',
    alignItems: 'center',
  },

  headerIcon: {
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: '#0284c7',
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 10,
  },

  headerTitle: {
    fontSize: 18,
    fontWeight: '700',
    color: '#ffffff',
  },

  headerSub: {
    fontSize: 11,
    color: '#e0f2fe',
  },

  badge: {
    paddingHorizontal: 10,
    paddingVertical: 4,
    borderRadius: 999,
  },

  badgeOnline: {
    backgroundColor: '#bbf7d0',
  },

  badgeOffline: {
    backgroundColor: '#fecaca',
  },

  badgeText: {
    fontSize: 11,
    fontWeight: '700',
    color: '#0f172a',
  },

  body: {
    flex: 1,
    backgroundColor: '#e0f2fe', // xanh nhạt
    borderTopLeftRadius: 24,
    borderTopRightRadius: 24,
    padding: 16,
  },

  tabBar: {
    flexDirection: 'row',
    backgroundColor: '#ffffff',
    borderRadius: 999,
    padding: 4,
    marginBottom: 12,
  },

  tabItem: {
    flex: 1,
    paddingVertical: 8,
    borderRadius: 999,
    alignItems: 'center',
  },

  tabItemActive: {
    backgroundColor: '#f472b6', // hồng
  },

  tabText: {
    fontSize: 12,
    fontWeight: '600',
    color: '#475569',
  },

  tabTextActive: {
    color: '#ffffff',
  },
});

export default App;
